// route below just calls eventBus.publish(workspaceId, buildTestEvent(...)) — no separate code
// path, no separate SSE plumbing). Unit-testable without a real Redis/session.
function buildTestEvent(rawType,overrides={},now=Date.now()){
  const type=ALLOWED_EVENT_TYPES.has(rawType)?rawType:'gift';
  const event={
    id:`test-${crypto.randomUUID()}`,
    type,
    userId:S.safeText(overrides.userId,160)||'test-user',
    username:S.safeText(overrides.username,120)||(type==='gift'?'TestGifter':'TestUser'),
    profileUrl:S.safeText(overrides.profileUrl,1200)||'assets/images/test-profile.svg',
    count:Math.max(1,Math.min(1e6,Number(overrides.count)||1)),
    value:Math.max(0,Math.min(1e9,Number(overrides.value)||(type==='gift'?1:0))),
    at:now
  };
  if(type==='gift'){
    event.giftId=S.safeText(overrides.giftId,160)||'test-gift-rose';
    event.giftName=S.safeText(overrides.giftName,160)||'Rose';
    event.giftImage=S.safeText(overrides.giftImage,1200)||'assets/gifts/part1/gifts/0001_Rose.png';
  }
  return event;
}
